std::list<Triangulation::Face_handle> queue;
for (Triangulation::All_faces_iterator current_face = triangulation.all_faces_begin(); current_face != triangulation.all_faces_end(); ++current_face) {
    if (current_face->info().processed) continue;
    if (current_face->is_constrained() && !current_face->info().interior) {
        current_face->info().interior = true;
        queue.push_back(current_face);
    }
}
while (!queue.empty()) {
    Triangulation::Face_handle current_face = queue.front();
    queue.pop_front();
    for (int i = 0; i < 3; ++i) {
        Triangulation::Face_handle neighbor = current_face->neighbor(i);
        if (neighbor->info().processed) continue;
        if (current_face->is_constrained(i)) {
            neighbor->info().interior = !current_face->info().interior;
        } else {
            neighbor->info().interior = current_face->info().interior;
        }
        neighbor->info().processed = true;
        queue.push_back(neighbor);
    }
}

